def fetch_upstream(req):
    conn = pool.acquire(req.host)
    try:
        return conn.send(req)
    finally:
        pool.release(conn)

def cache_key(req):
    parts = [req.method, req.path]
    for h in sorted(req.vary_headers):
        parts.append(req.headers.get(h, ""))
    return "v1:" + sha1("|".join(parts))

def get_cached(key):
    entry = _table.get(key)
    if entry is None or entry.expired():
        return None
    return entry.value

def store(key, resp, ttl):
    _table[key] = Entry(resp, now() + ttl)
    _evict_if_needed()

def _evict_if_needed():
    if _table.size() < HIGH_WATER:
        return
    target = _table.size() - LOW_WATER
    victims = []
    for shard in _table.shards():
        with shard.lock():
            for key, e in shard.items():
                if e.expired():
                    victims.append((INF, key))
                    continue
                score = now() - e.last_used
                if e.size > BIG_OBJECT:
                    score *= 2
                victims.append((score, key))
    victims.sort(reverse=True)
    for _, key in victims[:target]:
        _table.delete(key)
    metrics.evicted(target)
